@CheckData(name = "ExploitB", stableKey = "grim.exploit.invalid_book_edit", description = "Invalid book edit")
public class ExploitB extends Check implements PacketReceiveListener {
    private static final int BOOK_EXPECTED_SLOT = 0;
    private static final int BOOK_EXPECTED_TYPE = 1;
    private static final int BOOK_EXPECTED_AMOUNT = 2;
    private static final int BOOK_EXPECTED_META = 3;
    private static final int BOOK_NO_NBT = 4;
    private static final int BOOK_NO_PAGES = 5;
    private static final int BOOK_NO_TITLE = 6;
    private static final int BOOK_EXPECTED_AUTHOR = 7;
    private static final int BOOK_INVALID_PAGE = 8;
    private static final int BOOK_MODIFIED_NBT = 9;
    private static final int BOOK_TITLE_TOO_LONG = 10;
    private static final int BOOK_INVALID_TITLE = 11;
    private static final int BOOK_NOT_EDITING = 12;
    private static final int BOOK_TOO_MANY_PAGES = 13;
    private static final int BOOK_PAGE_TOO_LONG = 14;
    private static final int BOOK_EMPTY_LAST_PAGE = 15;

    // One shape per BOOK_* kind; shape index == constant value.
    private static final Verbose V = Verbose
            .of("expectedSlot={sint}, slot={sint}")      // BOOK_EXPECTED_SLOT
            .or("expectedType={item}, type={item}")      // BOOK_EXPECTED_TYPE
            .or("expectedAmount={sint}, amount={sint}")  // BOOK_EXPECTED_AMOUNT
            .or("expectedMeta={sint}, meta={sint}")      // BOOK_EXPECTED_META
            .or("no nbt")                                // BOOK_NO_NBT
            .or("no pages")                              // BOOK_NO_PAGES
            .or("no title")                              // BOOK_NO_TITLE
            .or("expectedAuthor={str}, author={str}")    // BOOK_EXPECTED_AUTHOR
            .or("invalid page")                          // BOOK_INVALID_PAGE
            .or("modified nbt")                          // BOOK_MODIFIED_NBT
            .or("title too long")                        // BOOK_TITLE_TOO_LONG
            .or("invalid title '{str}'")                 // BOOK_INVALID_TITLE
            .or("not editing book")                      // BOOK_NOT_EDITING
            .or("too many pages")                        // BOOK_TOO_MANY_PAGES
            .or("page too long")                         // BOOK_PAGE_TOO_LONG
            .or("empty last page");                      // BOOK_EMPTY_LAST_PAGE

    private static final int UNUSED_TYPE = -1;
    private static final boolean IS_1_8 = PacketEvents.getAPI().getServerManager().getVersion().isOlderThanOrEquals(ServerVersion.V_1_8_8);
    private ItemStack oldBook;
    private InteractionHand hand;

    public ExploitB(GrimPlayer player) {
        super(player);
    }

    @Override
    public void onPacketReceive(PacketReceiveEvent event) {
        if (IS_1_8 ? event.getPacketType() == PacketType.Play.Client.PLAYER_BLOCK_PLACEMENT
                && new WrapperPlayClientPlayerBlockPlacement(event).getFaceId() == 255
                : event.getPacketType() == PacketType.Play.Client.USE_ITEM) {
            hand = IS_1_8 ? InteractionHand.MAIN_HAND : new WrapperPlayClientUseItem(event).getHand();
            oldBook = player.inventory.getItemInHand(hand).copy();
        }

        if (event.getPacketType() == PacketType.Play.Client.EDIT_BOOK) {
            checkEditBook(new WrapperPlayClientEditBook(event), event);
            oldBook = null;
        }

        // 1.13-
        if (event.getPacketType() == PacketType.Play.Client.PLUGIN_MESSAGE && PacketEvents.getAPI().getServerManager().getVersion().isOlderThan(ServerVersion.V_1_13)) {
            WrapperPlayClientPluginMessage wrapper = new WrapperPlayClientPluginMessage(event);

            boolean signing;
            switch (wrapper.getChannelName()) {
                case "MC|BSign" -> signing = true;
                case "MC|BEdit" -> signing = false;
                default -> {
                    return;
                }
            }

            ItemStack newBook = new PayloadBookEdit(wrapper.getData()).itemStack();
            checkItemStack(newBook, signing, event);
            oldBook = null;
        }
    }

    private void checkEditBook(WrapperPlayClientEditBook wrapper, PacketReceiveEvent event) {
        if (checkEditingBook(event)) return;

        int expectedSlot = hand == InteractionHand.OFF_HAND ? 40 : player.packetStateData.lastSlotSelected;
        int slot = wrapper.getSlot();
        if (slot != expectedSlot) {
            flagExpectedSlot(event, expectedSlot, slot);
            return;
        }

        if (wrapper.getSigning() == null) { // 1.17+
            if (wrapper.getTitle() != null && checkTitle(wrapper.getTitle(), event)) return;

            List<String> pages = wrapper.getPages();
            if (pages.size() > 1 && checkEmptyLastPage(pages.get(pages.size() - 1), event)) return;
            if (checkTooManyPages(pages.size(), event)) return;
            for (String page : pages) {
                if (checkPage(page, event)) return;
            }
        } else { // 1.13 - 1.16.5
            checkItemStack(wrapper.getItemStack(), wrapper.getSigning(), event);
        }
    }

    private void checkItemStack(ItemStack newBook, boolean signing, PacketReceiveEvent event) {
        if (checkEditingBook(event)) return;

        ItemType expectedType = signing && IS_1_8 ? ItemTypes.WRITTEN_BOOK : ItemTypes.WRITABLE_BOOK;
        if (!newBook.is(expectedType)) {
            flagExpectedType(event, expectedType, newBook.getType());
            return;
        }

        if (newBook.getAmount() != oldBook.getAmount()) {
            flagExpectedAmount(event, oldBook.getAmount(), newBook.getAmount());
            return;
        }

        if (newBook.getLegacyData() != oldBook.getLegacyData()) {
            flagExpectedMeta(event, oldBook.getLegacyData(), newBook.getLegacyData());
            return;
        }

        NBTCompound newBookNBT = newBook.getNBT();
        if (newBookNBT == null) {
            flagLiteral(event, BOOK_NO_NBT);
            return;
        }

        NBTList<@NotNull NBTString> newPagesNBT = newBookNBT.getStringListTagOrNull("pages");
        if (newPagesNBT == null) {
            flagLiteral(event, BOOK_NO_PAGES);
            return;
        }

        if (checkTooManyPages(newPagesNBT.size(), event)) return;

        if (signing) {
            String title = newBookNBT.getStringTagValueOrNull("title");
            if (title == null) {
                flagLiteral(event, BOOK_NO_TITLE);
                return;
            }

            if (checkTitle(title, event)) return;

            String author = newBookNBT.getStringTagValueOrNull("author");
            if (!player.getName().equals(author)) {
                flagExpectedAuthor(event, player.getName(), author == null ? "null" : author);
                return;
            }
        }

        String last = null;
        for (NBTString string : newPagesNBT.getTags()) {
            if (IS_1_8 && signing) {
                try {
                    JsonReader reader = new JsonReader(new StringReader(string.getValue()));
                    if (reader.peek() != JsonToken.BEGIN_OBJECT) throw new JsonSyntaxException("");
                    reader.beginObject();
                    if (reader.peek() != JsonToken.NAME || !reader.nextName().equals("text")
                            || reader.peek() != JsonToken.STRING) throw new JsonSyntaxException("");
                    last = reader.nextString();
                    if (reader.peek() != JsonToken.END_OBJECT) throw new JsonSyntaxException("");
                } catch (JsonSyntaxException e) {
                    flagLiteral(event, BOOK_INVALID_PAGE);
                    return;
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            } else {
                last = string.getValue();
            }

            if (checkPage(last, event)) return;
        }

        if (last != null && checkEmptyLastPage(last, event)) {
            return;
        }

        Set<Map.Entry<String, NBT>> newNBT = newBookNBT.getTags().entrySet();
        HashMap<String, NBT> oldNBT = oldBook.getNBT() == null ? new HashMap<>() : new HashMap<>(oldBook.getNBT().getTags());
        oldNBT.remove("pages");
        oldNBT.remove("title");
        oldNBT.remove("author");
        for (var entry : newNBT) {
            if (!entry.getKey().equals("pages") && !entry.getKey().equals("title") && !entry.getKey().equals("author")) {
                NBT nbt = oldNBT.remove(entry.getKey());
                if (nbt == null || !nbt.equals(entry.getValue())) {
                    flagLiteral(event, BOOK_MODIFIED_NBT);
                    return;
                }
            }
        }

        if (!oldNBT.isEmpty()) {
            flagLiteral(event, BOOK_MODIFIED_NBT);
        }
    }

    private boolean checkTitle(@NotNull String title, PacketReceiveEvent event) {
        if (title.length() > (player.getClientVersion().isNewerThanOrEquals(ClientVersion.V_1_16) ? 15 : 16)) {
            flagLiteral(event, BOOK_TITLE_TOO_LONG);
            return true;
        } else if (title.isEmpty() || !title.trim().equals(title) || containsInvalidCharacters(title, false)) {
            flagInvalidTitle(event, title);
            return true;
        }

        return false;
    }

    private boolean checkEditingBook(PacketReceiveEvent event) {
        if (oldBook == null || !oldBook.is(ItemTypes.WRITABLE_BOOK)) {
            flagLiteral(event, BOOK_NOT_EDITING);
            return true;
        }
        return false;
    }

    private boolean checkTooManyPages(int pages, PacketReceiveEvent event) {
        NBTList<@NotNull NBTString> oldPagesNBT;
        int oldPages = oldBook.getVersion().isNewerThanOrEquals(ClientVersion.V_1_20_5)
                ? oldBook.getComponent(ComponentTypes.WRITABLE_BOOK_CONTENT).map(content -> content.getPages().size()).orElse(0)
                : oldBook.getNBT() != null && (oldPagesNBT = oldBook.getNBT().getStringListTagOrNull("pages")) != null
                ? oldPagesNBT.size() : 0;

        if (pages > oldPages && pages > (player.getClientVersion().isNewerThanOrEquals(ClientVersion.V_1_14) ? 100 : 50)) {
            flagLiteral(event, BOOK_TOO_MANY_PAGES);
            return true;
        }

        return false;
    }

    private boolean checkPage(String page, PacketReceiveEvent event) {
        if (page.length() > (player.getClientVersion().isNewerThanOrEquals(ClientVersion.V_1_14) ? 1023 : 256)) {
            flagLiteral(event, BOOK_PAGE_TOO_LONG);
            return true;
        }

        // commented out because existing characters are not considered
//        if (containsInvalidCharacters(page, true)) {
//            if (flag("invalid page characters") && shouldModifyPackets()) {
//                event.setCancelled(true);
//                player.onPacketCancel();
//            }
//            return true;
//        }

        return false;
    }

    private boolean checkEmptyLastPage(String page, PacketReceiveEvent event) {
        if (page.isEmpty()) {
            flagLiteral(event, BOOK_EMPTY_LAST_PAGE);
            return true;
        }

        return false;
    }

    private void flagExpectedSlot(PacketReceiveEvent event, int expectedSlot, int slot) {
        flagBookEdit(event, V.write(verbose(), BOOK_EXPECTED_SLOT).sint(expectedSlot).sint(slot));
    }

    private void flagExpectedType(PacketReceiveEvent event, @NotNull ItemType expectedType, @Nullable ItemType type) {
        flagBookEdit(event, V.write(verbose(), BOOK_EXPECTED_TYPE).sint(typeId(expectedType)).sint(typeId(type)));
    }

    private void flagExpectedAmount(PacketReceiveEvent event, int expectedAmount, int amount) {
        flagBookEdit(event, V.write(verbose(), BOOK_EXPECTED_AMOUNT).sint(expectedAmount).sint(amount));
    }

    private void flagExpectedMeta(PacketReceiveEvent event, int expectedMeta, int meta) {
        flagBookEdit(event, V.write(verbose(), BOOK_EXPECTED_META).sint(expectedMeta).sint(meta));
    }

    private void flagExpectedAuthor(PacketReceiveEvent event, @NotNull String expectedAuthor, @NotNull String author) {
        flagBookEdit(event, V.write(verbose(), BOOK_EXPECTED_AUTHOR).str(expectedAuthor).str(author));
    }

    private void flagInvalidTitle(PacketReceiveEvent event, @NotNull String title) {
        flagBookEdit(event, V.write(verbose(), BOOK_INVALID_TITLE).str(title));
    }

    private void flagLiteral(PacketReceiveEvent event, int kind) {
        flagBookEdit(event, V.write(verbose(), kind));
    }

    private void flagBookEdit(PacketReceiveEvent event, Verbose.Writer writer) {
        if (flag(writer) && shouldModifyPackets()) {
            event.setCancelled(true);
            player.onPacketCancel();
        }
    }

    private int typeId(@Nullable ItemType type) {
        return type == null ? UNUSED_TYPE : VerboseCodecs.item(type, player.getClientVersion());
    }

    private static boolean containsInvalidCharacters(@NotNull String string, boolean allowLineBreak) {
        for (int i = 0; i < string.length(); ++i) {
            char character = string.charAt(i);
            if (character == 167 || character < 32 && (!allowLineBreak || character != 10) || character == 127) {
                return true;
            }
        }

        return false;
    }
}

